You are Einstein's improvement executor for TESSERA Round 3 candidate R3-04.

## Goal
Speed up hybrid-retrieval rerank: replace sequential `await generateEmbedding` per chunk with one `generateEmbeddingsBatch` call. Same scores, fewer round-trips / much lower wall time when reranking topK chunks.

## Exact change
File: artifacts/api-server/src/lib/hybrid-retrieval.ts

1. Change import from:
`import { generateEmbedding, cosineSimilarity } from "./neural-embeddings";`
to:
`import { generateEmbedding, generateEmbeddingsBatch, cosineSimilarity } from "./neural-embeddings";`

2. Replace rerankByEmbedding:
```
async function rerankByEmbedding(query: string, chunks: RetrievedChunk[]): Promise<RetrievedChunk[]> {
  try {
    const qEmb = await generateEmbedding(query);
    if (!qEmb || qEmb.length === 0) return chunks;
    const scored: RetrievedChunk[] = [];
    for (const c of chunks) {
      try {
        const cEmb = await generateEmbedding(c.text.slice(0, 800));
        const sim = cosineSimilarity(qEmb, cEmb);
        scored.push({ ...c, rerankScore: sim, score: 0.5 * c.score + 0.5 * sim });
      } catch {
        scored.push(c);
      }
    }
    scored.sort((a, b) => b.score - a.score);
    return scored;
  } catch (err) {
    logger.debug({ err: (err as Error).message }, "hybrid: rerank failed");
    return chunks;
  }
}
```
with:
```
async function rerankByEmbedding(query: string, chunks: RetrievedChunk[]): Promise<RetrievedChunk[]> {
  try {
    const qEmb = await generateEmbedding(query);
    if (!qEmb || qEmb.length === 0) return chunks;
    const texts = chunks.map((c) => c.text.slice(0, 800));
    const embeddings = await generateEmbeddingsBatch(texts);
    const scored: RetrievedChunk[] = chunks.map((c, i) => {
      const cEmb = embeddings[i];
      if (!cEmb || cEmb.length === 0) return c;
      const sim = cosineSimilarity(qEmb, cEmb);
      return { ...c, rerankScore: sim, score: 0.5 * c.score + 0.5 * sim };
    });
    scored.sort((a, b) => b.score - a.score);
    return scored;
  } catch (err) {
    logger.debug({ err: (err as Error).message }, "hybrid: rerank failed");
    return chunks;
  }
}
```

